solution_code.code:
// components/Avatar.jsx
function Avatar(props) {
  return <img className="circle-img" src={props.img} alt="avatar" />;
}
export default Avatar;

// components/Detail.jsx
function Detail(props) {
  return <p className="info">{props.detailInfo}</p>;
}
export default Detail;

// components/Card.jsx: receives props from App and hands them on
import Avatar from "./Avatar";
import Detail from "./Detail";

function Card(props) {
  return (
    <div className="card">
      <div className="top">
        <h2 className="name">{props.name}</h2>
        <Avatar img={props.img} />
      </div>
      <div className="bottom">
        <Detail detailInfo={props.tel} />
        <Detail detailInfo={props.email} />
      </div>
    </div>
  );
}
export default Card;

// App.jsx (still indexing the array by hand at this point)
import Card from "./components/Card";
import Avatar from "./components/Avatar";
import { contacts } from "./contacts";

function App() {
  return (
    <div>
      <h1 className="heading">My Contacts</h1>
      <Avatar img="https://example.com/me.jpg" />
      <Card name={contacts[0].name} img={contacts[0].imgURL} tel={contacts[0].phone} email={contacts[0].email} />
      <Card name={contacts[1].name} img={contacts[1].imgURL} tel={contacts[1].phone} email={contacts[1].email} />
      <Card name={contacts[2].name} img={contacts[2].imgURL} tel={contacts[2].phone} email={contacts[2].email} />
    </div>
  );
}
export default App;
